// slide_041.js — "Chess" scatter plot generated by "for loops"
// House frame + checkerboard scatter pattern from exact 64 coordinates
// Run: NODE_PATH=$(npm root -g) node slide_041.js

const pptxgen = require("pptxgenjs");

const NUM = 41;
const FONT = "Arial";

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE";
const W = 13.33, H = 7.5;
const s = pres.addSlide();
s.background = { color: "E8E8E8" };

// 1. House red frame (0.15in inset)
s.addShape(pres.shapes.RECTANGLE, {
  x: 0.15, y: 0.15, w: W - 0.3, h: H - 0.3,
  fill: { type: "none" },
  line: { color: "C00000", width: 1.5 },
});

// 2. Slide-number badge
s.addShape(pres.shapes.OVAL, {
  x: 12.48, y: 0.30, w: 0.5, h: 0.5,
  fill: { color: "FFF9C4" }, line: { color: "FFF9C4", width: 0.5 },
});
s.addText(String(NUM), {
  x: 12.48, y: 0.30, w: 0.5, h: 0.5,
  align: "center", valign: "middle",
  fontSize: 18, bold: true, color: "333333", fontFace: FONT, margin: 0,
});

// 3. Title box (intentionally empty per house-chrome rule — original has no centered title)
s.addText("", {
  x: 0.6, y: 0.28, w: 12.13, h: 0.55,
  align: "center", valign: "top",
  fontSize: 24, bold: true, color: "C00000", fontFace: FONT, margin: 0,
});

// 4. Bottom black footer bar
s.addShape(pres.shapes.RECTANGLE, {
  x: 0.15, y: H - 0.15 - 0.35, w: W - 0.3, h: 0.35,
  fill: { color: "000000" }, line: { type: "none" },
});

// 5. Title box (white rounded rectangle at top-left) — per vision analysis
s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 0.6, y: 1.5, w: 3.0, h: 1.4,
  fill: { color: "FFFFFF" },
  line: { color: "CCCCCC", width: 0.5 },
});
s.addText("Chess", {
  x: 0.6, y: 1.65, w: 3.0, h: 0.55,
  align: "center", valign: "top",
  fontSize: 28, bold: true, italic: true, color: "C00000", fontFace: FONT, margin: 0,
});
s.addText('Generated by "for loops"', {
  x: 0.6, y: 2.25, w: 3.0, h: 0.35,
  align: "center", valign: "top",
  fontSize: 12, color: "0000FF", fontFace: FONT, margin: 0,
});

// 6. Scatter plot panel (center-right)
// Panel at approximately x=5.0, y=1.2, w=7.3, h=5.3 (inches)
const plotX = 5.0;
const plotY = 1.2;
const plotW = 7.3;
const plotH = 5.3;

// Plot background (white)
s.addShape(pres.shapes.RECTANGLE, {
  x: plotX, y: plotY, w: plotW, h: plotH,
  fill: { color: "FFFFFF" },
  line: { color: "CCCCCC", width: 1.0 },
});

// Axes: 0-25 on both x and y, gridlines at 0,5,10,15,20,25
const X_MIN = 0, X_MAX = 25;
const Y_MIN = 0, Y_MAX = 25;
const ticks = [0, 5, 10, 15, 20, 25];

// Gridlines (light gray)
ticks.forEach(t => {
  if (t === 0) return;
  // Vertical gridlines
  const gx = plotX + (t - X_MIN) / (X_MAX - X_MIN) * plotW;
  s.addShape(pres.shapes.LINE, {
    x: gx, y: plotY, w: 0, h: plotH,
    line: { color: "E8E8E8", width: 0.5 },
  });
  // Horizontal gridlines
  const gy = plotY + plotH - (t - Y_MIN) / (Y_MAX - Y_MIN) * plotH;
  s.addShape(pres.shapes.LINE, {
    x: plotX, y: gy, w: plotW, h: 0,
    line: { color: "E8E8EE", width: 0.5 },
  });
});

// Tick labels (black)
ticks.forEach(t => {
  // X-axis labels
  const tx = plotX + (t - X_MIN) / (X_MAX - X_MIN) * plotW;
  s.addText(String(t), {
    x: tx - 0.25, y: plotY + plotH + 0.05, w: 0.5, h: 0.25,
    align: "center", fontSize: 9, color: "000000", fontFace: FONT, margin: 0,
  });
  // Y-axis labels
  const ty = plotY + plotH - (t - Y_MIN) / (Y_MAX - Y_MIN) * plotH;
  s.addText(String(t), {
    x: plotX - 0.35, y: ty - 0.1, w: 0.3, h: 0.2,
    align: "right", fontSize: 9, color: "000000", fontFace: FONT, margin: 0,
  });
});

// 7. Exact 64-dot checkerboard pattern from recreation_brief
// blue at (3,22), (4,22), (3,21), (4,21); red at (9,22), (10,22), (9,21), (10,21); ...
const dots = [
  // Row y≈22
  {x: 3, y: 22, c: "2A57D8"}, {x: 4, y: 22, c: "2A57D8"}, {x: 3, y: 21, c: "2A57D8"}, {x: 4, y: 21, c: "2A57D8"},
  {x: 9, y: 22, c: "D82A2A"}, {x: 10, y: 22, c: "D82A2A"}, {x: 9, y: 21, c: "D82A2A"}, {x: 10, y: 21, c: "D82A2A"},
  {x: 14, y: 22, c: "2A57D8"}, {x: 15, y: 22, c: "2A57D8"}, {x: 14, y: 21, c: "2A57D8"}, {x: 15, y: 21, c: "2A57D8"},
  {x: 19, y: 22, c: "D82A2A"}, {x: 20, y: 22, c: "D82A2A"}, {x: 19, y: 21, c: "D82A2A"}, {x: 20, y: 21, c: "D82A2A"},
  // Row y≈15
  {x: 3, y: 15, c: "D82A2A"}, {x: 4, y: 15, c: "D82A2A"}, {x: 3, y: 14, c: "D82A2A"}, {x: 4, y: 14, c: "D82A2A"},
  {x: 9, y: 16, c: "2A57D8"}, {x: 10, y: 16, c: "2A57D8"}, {x: 9, y: 15, c: "2A57D8"}, {x: 10, y: 15, c: "2A57D8"},
  {x: 14, y: 16, c: "D82A2A"}, {x: 15, y: 16, c: "D82A2A"}, {x: 14, y: 15, c: "D82A2A"}, {x: 15, y: 15, c: "D82A2A"},
  {x: 19, y: 16, c: "2A57D8"}, {x: 20, y: 16, c: "2A57D8"}, {x: 19, y: 15, c: "2A57D8"}, {x: 20, y: 15, c: "2A57D8"},
  // Row y≈10
  {x: 3, y: 10, c: "2A57D8"}, {x: 4, y: 10, c: "2A57D8"}, {x: 3, y: 9, c: "2A57D8"}, {x: 4, y: 9, c: "2A57D8"},
  {x: 9, y: 10, c: "D82A2A"}, {x: 10, y: 10, c: "D82A2A"}, {x: 9, y: 9, c: "D82A2A"}, {x: 10, y: 9, c: "D82A2A"},
  {x: 14, y: 10, c: "2A57D8"}, {x: 15, y: 10, c: "2A57D8"}, {x: 14, y: 9, c: "2A57D8"}, {x: 15, y: 9, c: "2A57D8"},
  {x: 19, y: 10, c: "D82A2A"}, {x: 20, y: 10, c: "D82A2A"}, {x: 19, y: 9, c: "D82A2A"}, {x: 20, y: 9, c: "D82A2A"},
  // Row y≈4
  {x: 3, y: 4, c: "D82A2A"}, {x: 4, y: 4, c: "D82A2A"}, {x: 3, y: 3, c: "D82A2A"}, {x: 4, y: 3, c: "D82A2A"},
  {x: 9, y: 4, c: "2A57D8"}, {x: 10, y: 4, c: "2A57D8"}, {x: 9, y: 3, c: "2A57D8"}, {x: 10, y: 3, c: "2A57D8"},
  {x: 14, y: 4, c: "D82A2A"}, {x: 15, y: 4, c: "D82A2A"}, {x: 14, y: 3, c: "D82A2A"}, {x: 15, y: 3, c: "D82A2A"},
  {x: 19, y: 4, c: "2A57D8"}, {x: 20, y: 4, c: "2A57D8"}, {x: 19, y: 3, c: "2A57D8"}, {x: 20, y: 3, c: "2A57D8"},
];

dots.forEach(d => {
  const xNorm = (d.x - X_MIN) / (X_MAX - X_MIN);
  const yNorm = (d.y - Y_MIN) / (Y_MAX - Y_MIN);
  const cx = plotX + xNorm * plotW;
  const cy = plotY + plotH - yNorm * plotH;
  s.addShape(pres.shapes.OVAL, {
    x: cx - 0.07, y: cy - 0.07, w: 0.14, h: 0.14,
    fill: { color: d.c }, line: { type: "none" },
  });
});

pres.writeFile({ 
  fileName: "/home/codespace/ai_llm_slides/videos/machine-learning/06_svm_with_kernels_quadratic_programming_libraries/recreated_pptx/slide_041_recreated.pptx" 
}).then(() => console.log("wrote slide_041_recreated.pptx"))
.catch(err => console.error(err));